#[derive(PartialEq, Eq, Clone, Debug)]
pub struct ListNode {
    pub val: i32,
    pub next: Option<Box<ListNode>>,
}

impl ListNode {
    #[inline]
    pub fn new(val: i32) -> Self {
        ListNode { next: None, val }
    }
}

pub struct Solution;

impl Solution {
    fn merge_two_lists(
        mut l1: Option<Box<ListNode>>,
        mut l2: Option<Box<ListNode>>,
    ) -> Option<Box<ListNode>> {
        let mut dummy = ListNode::new(0);
        let mut tail = &mut dummy;

        while l1.is_some() && l2.is_some() {
            if l1.as_ref().unwrap().val <= l2.as_ref().unwrap().val {
                let next = l1.as_mut().unwrap().next.take();
                tail.next = l1;
                tail = tail.next.as_mut().unwrap();
                l1 = next;
            } else {
                let next = l2.as_mut().unwrap().next.take();
                tail.next = l2;
                tail = tail.next.as_mut().unwrap();
                l2 = next;
            }
        }

        tail.next = if l1.is_some() { l1 } else { l2 };
        dummy.next
    }

    pub fn merge_k_lists(lists: Vec<Option<Box<ListNode>>>) -> Option<Box<ListNode>> {
        if lists.is_empty() {
            return None;
        }

        let mut lists = lists;
        let mut interval = 1;
        let n = lists.len();

        while interval < n {
            for i in (0..n - interval).step_by(interval * 2) {
                let l1 = lists[i].take();
                let l2 = lists[i + interval].take();
                lists[i] = Self::merge_two_lists(l1, l2);
            }
            interval *= 2;
        }

        lists[0].take()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn to_list(vals: &[i32]) -> Option<Box<ListNode>> {
        let mut head = None;
        for &val in vals.iter().rev() {
            let mut node = Box::new(ListNode::new(val));
            node.next = head;
            head = Some(node);
        }
        head
    }

    fn to_vec(mut head: Option<Box<ListNode>>) -> Vec<i32> {
        let mut result = Vec::new();
        while let Some(node) = head {
            result.push(node.val);
            head = node.next;
        }
        result
    }

    #[test]
    fn test_example_1() {
        let lists = vec![to_list(&[1, 4, 5]), to_list(&[1, 3, 4]), to_list(&[2, 6])];
        let merged = Solution::merge_k_lists(lists);
        assert_eq!(to_vec(merged), vec![1, 1, 2, 3, 4, 4, 5, 6]);
    }

    #[test]
    fn test_example_2_empty_lists() {
        let lists: Vec<Option<Box<ListNode>>> = vec![];
        let merged = Solution::merge_k_lists(lists);
        assert_eq!(to_vec(merged), Vec::<i32>::new());
    }

    #[test]
    fn test_example_3_list_of_empty() {
        let lists = vec![None];
        let merged = Solution::merge_k_lists(lists);
        assert_eq!(to_vec(merged), Vec::<i32>::new());
    }

    #[test]
    fn test_negative_values() {
        let lists = vec![to_list(&[-10, -5, 0]), to_list(&[-8, -2, 3])];
        let merged = Solution::merge_k_lists(lists);
        assert_eq!(to_vec(merged), vec![-10, -8, -5, -2, 0, 3]);
    }

    #[test]
    fn test_single_list() {
        let lists = vec![to_list(&[1, 2, 3])];
        let merged = Solution::merge_k_lists(lists);
        assert_eq!(to_vec(merged), vec![1, 2, 3]);
    }
}
